let currentUser=null;
const getUser=()=>currentUser;
const readResult=async(kind)=>{const u=getUser();if(!u||!window.medstartDb)return null;try{const snap=await medstartDb.collection('users').doc(u.uid).collection('results').doc(kind).get();return snap.exists?snap.data():null}catch(err){console.error('Could not load result:',err);return null}};
const saveResult=async(kind,data)=>{const u=getUser();if(!u){alert('Please sign in before saving results to your dashboard.');return false}try{await medstartDb.collection('users').doc(u.uid).collection('results').doc(kind).set({...data,savedAt:new Date().toISOString(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});return true}catch(err){console.error(err);alert('Your result is shown, but could not be saved. Check the Firestore rules in the README and publish them in Firebase.');return false}};
async function refreshAuth(){const u=getUser();if($('authButton'))$('authButton').textContent=u?(u.displayName||u.email||'Account'):'Sign in / Sign up';if($('welcomeName'))$('welcomeName').textContent=u?'Welcome back, '+(u.displayName||u.email)+'. Your results are saved to your account.':'Sign in to view your private dashboard and saved quiz and medical-case results.';const dash=document.querySelector('.dashboard');if(dash)dash.hidden=!u;const [q,c]=u?await Promise.all([readResult('quiz'),readResult('case')]):[null,null];if($('quizSaved'))$('quizSaved').textContent=u?(q?q.summary+' (Saved '+(q.savedAt?new Date(q.savedAt).toLocaleString():'recently')+')':'No specialty quiz result saved yet.'):'Sign in to view results.';if($('caseSaved'))$('caseSaved').textContent=u?(c?c.summary+' (Saved '+(c.savedAt?new Date(c.savedAt).toLocaleString():'recently')+')':'No medical-case result saved yet.'):'Sign in to view results.'}
