 // Render every quiz answer as a tappable button, while retaining the underlying select values for scoring.
 document.querySelectorAll('#quizSteps select').forEach((select,idx)=>{
   if(!select.name.startsWith('rank_')){select.required=true;select.selectedIndex=-1;}
   select.classList.add('quiz-native-select');
   const group=document.createElement('div');group.className=select.name.startsWith('rank_')?'choice-buttons rank-choice-buttons':'choice-buttons';group.setAttribute('role','group');
   group.setAttribute('aria-label',select.closest('label,td')?.textContent.trim()||'Answer options');
   [...select.options].forEach(option=>{
     if(option.value==='')return;
     const button=document.createElement('button');button.type='button';button.className='choice-button';button.textContent=option.textContent.trim();button.setAttribute('aria-pressed','false');
     button.addEventListener('click',()=>{
       if(select.name.startsWith('rank_')){
         const table=select.closest('table');
         table.querySelectorAll('select').forEach(other=>{if(other!==select&&other.value===option.value){other.value='';other.closest('td').querySelectorAll('.choice-button').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')})}});
       }
       select.value=option.value;group.querySelectorAll('.choice-button').forEach(b=>{const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',active?'true':'false')});
     });group.appendChild(button);
   });
   select.insertAdjacentElement('afterend',group);
 });
 const quizSteps=[...document.querySelectorAll('#quizSteps .quiz-step')];let quizStepIndex=0;
 const renderQuizStep=()=>{quizSteps.forEach((step,i)=>{step.classList.toggle('active',i===quizStepIndex);step.setAttribute('aria-hidden',i===quizStepIndex?'false':'true')});$('quizProgress').textContent='Question '+(quizStepIndex+1)+' of '+quizSteps.length;$('quizPrev').disabled=quizStepIndex===0;$('quizNext').classList.toggle('hidden',quizStepIndex===quizSteps.length-1);$('quizFinish').classList.toggle('hidden',quizStepIndex!==quizSteps.length-1);};
 const currentStepValid=()=>{const fields=[...quizSteps[quizStepIndex].querySelectorAll('input,select,textarea')];for(const field of fields){if(field.tagName==='SELECT'&&!field.value){const group=field.nextElementSibling;if(group?.classList.contains('choice-buttons')){group.querySelector('.choice-button')?.focus();group.scrollIntoView({block:'nearest',behavior:'smooth'});group.classList.add('needs-answer');setTimeout(()=>group.classList.remove('needs-answer'),1200);return false}}else if(!field.checkValidity()){field.reportValidity();return false}}return true};
