let active=null,caseN=0;let previousCaseIds=[];
function startCase(){
  if(!bank.length)return;
  let candidates=bank.map((_,i)=>i).filter(i=>!previousCaseIds.includes(i));
  if(candidates.length<1){previousCaseIds=[];candidates=bank.map((_,i)=>i)}
  const idx=candidates[Math.floor(Math.random()*candidates.length)]; previousCaseIds.push(idx);
  if(previousCaseIds.length>Math.min(12,bank.length))previousCaseIds.shift();
  active=bank[idx];caseN++;
  $('caseCategory').textContent=active.cat;$('caseCounter').textContent='Case '+caseN+' · '+bank.length+' case scenarios in rotation';
  $('caseTitle').textContent=active.title;$('caseScenario').textContent=active.story;
  $('caseFeedback').classList.add('hidden');
  $('caseQuestions').innerHTML=active.q.map((q,i)=>{let opts=q[1].map((text,k)=>({text,k})).sort(()=>Math.random()-.5);return '<fieldset class="question" data-correct="'+opts.findIndex(o=>o.k===0)+'"><legend>'+(i+1)+'. '+q[0]+'</legend><div class="options">'+opts.map((o,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'" required> '+o.text+'</label>').join('')+'</div></fieldset>'}).join('');
}

if($('startCase'))$('startCase').onclick=startCase;
if($('caseForm'))$('caseForm').onsubmit=e=>{e.preventDefault();if(!active)return;let fd=new FormData(e.currentTarget),score=0;document.querySelectorAll('#caseQuestions fieldset').forEach((f,i)=>{let ans=Number(fd.get('q'+i)),correct=Number(f.dataset.correct);if(ans===correct)score++});let msg='Latest medical case: '+active.cat+' · '+active.title+' scored '+score+'/5.';$('caseFeedback').innerHTML='<b>Score: '+score+'/5.</b><br>'+msg+'<br><p>Review the scenario and discuss the reasoning with a qualified teacher or clinician. This is an educational vignette, not clinical advice.</p><button type="button" class="btn secondary" id="nextCase">Next different case →</button>';$('caseFeedback').classList.remove('hidden');if(getUser())saveResult('case',{summary:msg,category:active.cat,title:active.title,score:score,outOf:5}).then(refreshAuth);else alert('Your score is shown above. Sign in to save it to your home dashboard.');refreshAuth();$('nextCase').onclick=startCase};


